pub const PREFIX_RULES: &[(&str, &str)] = &[("af_alg", "kernel crypto socket tests skipped in broad LTP scan"), ("aio", "requires libaio userspace environment"), ("bpf_", "BPF syscall family not implemented"), ("cgroup_", "requires cgroup support"), ("cpuset", "cgroup controller helper"), ("ptrace", "ptrace subsystem not implemented"), ("sctp", "network SCTP tests skipped in LTP syscall scan"), ("tcp", "network TCP stress tests skipped in LTP syscall scan"), ("udp", "network UDP tests skipped in LTP syscall scan"), ("userns", "user namespace tests skipped in LTP syscall scan"), ("zram", "zram module tests skipped in LTP syscall scan")];
pub fn skip(name: &str) -> Option<&'static str> { PREFIX_RULES.iter().find(|(prefix, _)| name.starts_with(prefix)).map(|(_, reason)| *reason) }
